p_l2_init:

			; L2.cls 27: bankA = 16 : bankB = 19 : bg = backColour And 255
			dw kw_ltov, 16, var_l2_banka
			dw kw_ltov, 19, var_l2_bankb
			dw kw_andvl, var_l2_init_backcolour, 255, var_l2_bg

			; L2.cls 28: cnt0 = 0 : cnt1 = 0
			dw kw_ztov, var_l2_cnt0
			dw kw_ztov, var_l2_cnt1

			; L2.cls 29: Nx.Reg &H70, 0                         ' 256 x 192
			dw fn_nx_reg, lit_112, lit_0

			; L2.cls 30: Nx.Reg &H1C, 1                         ' its clip window: all of it
			dw fn_nx_reg, lit_28, lit_1

			; L2.cls 31: Nx.Reg &H18, 0 : Nx.Reg &H18, 255 : Nx.Reg &H18, 0 : Nx.Reg &H18, 191
			dw fn_nx_reg, lit_24, lit_0
			dw fn_nx_reg, lit_24, lit_255
			dw fn_nx_reg, lit_24, lit_0
			dw fn_nx_reg, lit_24, lit_191

			; L2.cls 32: Nx.Reg &H16, 0 : Nx.Reg &H17, 0        ' no scroll
			dw fn_nx_reg, lit_22, lit_0
			dw fn_nx_reg, lit_23, lit_0

			; L2.cls 33: cur = 1
			dw kw_ltov, 1, var_l2_cur

			; L2.cls 34: Wipe
			dw fn_l2_wipe

			; L2.cls 35: cur = 0
			dw kw_ztov, var_l2_cur

			; L2.cls 36: Wipe
			dw fn_l2_wipe

			; L2.cls 37: Nx.Reg &H12, bankB                     ' bank 19 shown, 16 drawn on
			dw fn_nx_reg, lit_18, var_l2_bankb

			; L2.cls 38: Out &H123B, 2                          ' Layer 2 visible
			dw kw_out, lit_4667, lit_2
			dw p_l2_init_r

